#!/usr/bin/env python3
"""Generate a data quality report from the committed price snapshot."""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

import pandas as pd

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT / "src") not in sys.path:
    sys.path.insert(0, str(ROOT / "src"))

from risk_lab.data import compute_returns, load_prices


def build_report(prices: pd.DataFrame, returns: pd.DataFrame) -> str:
    """Build the Markdown data quality report."""
    lines = [
        "# Data quality",
        "",
        "Generated by `scripts/data_quality.py` from `data/prices.csv`.",
        "",
        "## Overview",
        "",
        "| Metric | Value |",
        "|---|---:|",
        f"| Rows | {len(prices)} |",
        f"| First date | {prices.index.min().date()} |",
        f"| Last date | {prices.index.max().date()} |",
        f"| Assets | {', '.join(prices.columns)} |",
        f"| Missing values | {int(prices.isna().sum().sum())} |",
        f"| Duplicate dates | {int(prices.index.duplicated().sum())} |",
        "",
        "## Prices",
        "",
        "| Asset | First | Last | Minimum | Maximum |",
        "|---|---:|---:|---:|---:|",
    ]
    for column in prices.columns:
        series = prices[column]
        lines.append(
            f"| {column} | {series.iloc[0]:.2f} | {series.iloc[-1]:.2f} | "
            f"{series.min():.2f} | {series.max():.2f} |"
        )

    lines.extend(
        [
            "",
            "## Daily returns",
            "",
            "| Asset | Mean | Std | Minimum | Maximum | Worst date |",
            "|---|---:|---:|---:|---:|---|",
        ]
    )
    for column in returns.columns:
        series = returns[column]
        lines.append(
            f"| {column} | {series.mean():.4%} | {series.std(ddof=1):.4%} | "
            f"{series.min():.4%} | {series.max():.4%} | "
            f"{series.idxmin().date()} |"
        )

    lines.extend(
        [
            "",
            "## Observations by year",
            "",
            "| Year | Observations |",
            "|---:|---:|",
        ]
    )
    counts = prices.groupby(prices.index.year).size()
    for year, count in counts.items():
        lines.append(f"| {year} | {count} |")
    lines.append("")
    return "\n".join(lines)


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--data",
        type=Path,
        default=ROOT / "data" / "prices.csv",
        help="price CSV",
    )
    parser.add_argument(
        "--docs",
        type=Path,
        default=ROOT / "docs",
        help="output directory",
    )
    return parser.parse_args(argv)


def main(argv: list[str] | None = None) -> int:
    args = parse_args(argv)
    try:
        return _run(args)
    except (OSError, ValueError, KeyError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1


def _run(args: argparse.Namespace) -> int:
    prices = load_prices(args.data)
    returns = compute_returns(prices)
    report = build_report(prices, returns)
    args.docs.mkdir(parents=True, exist_ok=True)
    destination = args.docs / "data_quality.md"
    destination.write_text(report, encoding="utf-8", newline="\n")
    print(f"Wrote {destination}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
